def route_cache_tier(exact_hit: bool, semantic_hit: bool, prefix_overlap_tokens: int) -> str:
    if exact_hit:
        return 'L1_EXACT_HASH_HIT'
    if semantic_hit:
        return 'L2_SEMANTIC_HIT'
    if prefix_overlap_tokens >= 256:
        return 'L3_KV_PREFIX_REUSE_AND_DECODE'
    return 'FULL_PREFILL_AND_DECODE'

import hashlib
import json

def build_l1_key(tenant_id: str, model_id: str, temperature: float, messages: list[dict]) -> str:
    if not tenant_id or not model_id:
        raise ValueError('tenant_id and model_id are required')
    payload = {'t': tenant_id, 'm': model_id, 'temp': round(temperature, 2), 'msgs': messages}
    digest = hashlib.sha256(json.dumps(payload, sort_keys=True).encode('utf-8')).hexdigest()
    return f'llm:l1:{tenant_id}:{digest}'

import numpy as np

def cosine_similarity(a: np.ndarray, b: np.ndarray) -> float:
    denom = float(np.linalg.norm(a) * np.linalg.norm(b))
    if denom < 1e-12:
        return 0.0
    return float(np.dot(a, b) / denom)

def prefix_prefill_savings(total_prompt_tokens: int, cached_prefix_tokens: int) -> float:
    if total_prompt_tokens <= 0 or cached_prefix_tokens < 0:
        raise ValueError('Token counts must be valid')
    reused = min(total_prompt_tokens, cached_prefix_tokens)
    return round(reused / total_prompt_tokens, 4)

import hashlib

def route_prefix_worker(prefix_tokens: list[int], num_workers: int, max_load_ratio: float, worker_loads: list[float]) -> int:
    key = ','.join(map(str, prefix_tokens[:512])).encode('utf-8')
    primary = int(hashlib.sha256(key).hexdigest(), 16) % num_workers
    avg_load = sum(worker_loads) / max(1, len(worker_loads))
    if worker_loads[primary] <= avg_load * max_load_ratio:
        return primary
    return min(range(num_workers), key=lambda idx: worker_loads[idx])

def is_cache_entry_valid(entry_model: str, cur_model: str, entry_kb_ver: int, cur_kb_ver: int, age_sec: float, ttl_sec: float) -> bool:
    if entry_model != cur_model or entry_kb_ver != cur_kb_ver:
        return False
    return 0.0 <= age_sec <= ttl_sec
